function drawSpecialistsDirectory(){const value=s=>state.specialistSort==='name'?`${s.lastName} ${s.firstName}`:String(s[state.specialistSort]||''),people=[...state.specialists].sort((a,b)=>value(a).localeCompare(value(b),'pl',{numeric:true})*(state.specialistSortDirection==='asc'?1:-1)),header=(key,label)=>`<button class="table-sort" data-specialist-sort="${key}" type="button">${label}${state.specialistSort===key?state.specialistSortDirection==='asc'?' ↑':' ↓':' ↕'}</button>`,rows=people.map(s=>`<tr><td><strong>${esc(s.lastName)} ${esc(s.firstName)}</strong></td><td>${esc(s.specialization)}</td><td><span class="color-dot" style="background:${esc(s.color)}"></span>${esc(s.color)}</td><td><div class="table-actions"><button class="table-edit" data-specialist-id="${s.id}" type="button">Edytuj</button></div></td></tr>`).join('');$('directoryView').innerHTML=`<div class="directory-head"><div><h2>Specjaliści</h2><p>${people.length} osób w zespole</p></div><button class="primary-action" id="addSpecialist" type="button">＋ Dodaj specjalistę</button></div>${directoryTable([header('name','Nazwisko i imię'),header('specialization','Specjalizacja'),header('color','Kolor kalendarza'),''],rows)}`}
function drawPaymentsDirectory(){if(state.paymentAppointments===null){state.paymentAppointments=[...state.appointments];loadPaymentAppointments()}const rows=state.paymentAppointments.filter(a=>state.paymentStatus==='ALL'||(state.paymentStatus==='PAID')===a.paid).sort((a,b)=>new Date(b.startsAt)-new Date(a.startsAt)).map(a=>`<tr><td>${esc(client(a.clientId))}</td><td>${new Date(a.startsAt).toLocaleString('pl-PL',{dateStyle:'medium',timeStyle:'short'})}</td><td><input class="payment-input" data-payment-price="${a.id}" type="number" min="0" step="0.01" value="${Number(a.price).toFixed(2)}"> zł</td><td><select class="payment-status" data-payment-paid="${a.id}"><option value="false" ${a.paid?'':'selected'}>Do zapłaty</option><option value="true" ${a.paid?'selected':''}>Zapłacona</option></select></td><td><button class="table-edit" data-save-payment="${a.id}" type="button">Zapisz</button></td></tr>`).join('');$('directoryView').innerHTML=`<div class="directory-head"><div><h2>Płatności</h2><p>Edytuj kwotę lub status i zapisz zmianę.${state.paymentLoading?' Wczytywanie pełnego zakresu…':state.paymentError?` ${state.paymentError}`:''}</p></div><div class="payment-filter"><label>Zakres <select id="paymentRange"><option value="CURRENT_WEEK">Aktualny tydzień</option><option value="LAST_WEEK">Ostatni tydzień i aktualny</option><option value="TWO_WEEKS">Ostatnie 2 tygodnie i aktualny</option><option value="MONTH">Ostatni miesiąc</option><option value="THREE_MONTHS">Ostatnie 3 miesiące</option></select></label><label>Status <select id="paymentStatus"><option value="ALL">Wszystkie</option><option value="PAID">Zapłacone</option><option value="UNPAID">Do zapłaty</option></select></label></div></div>${directoryTable(['Klient','Termin','Kwota','Status',''],rows)}`;$('paymentRange').value=state.paymentRange;$('paymentStatus').value=state.paymentStatus}
async function savePayment(id){
 const input=document.querySelector('[data-payment-price="'+id+'"]'),button=document.querySelector('[data-save-payment="'+id+'"]');
 if(!input.reportValidity()||input.value==='')return;
 button.disabled=true;
 try{const r=await api('/api/appointments/'+id+'/payment',{method:'PATCH',body:JSON.stringify({price:Number(input.value),paid:document.querySelector('[data-payment-paid="'+id+'"]').value==='true'})});if(!r.ok){const d=await r.json();throw Error(d.message||'Nie udało się zapisać płatności.')}const updated=await r.json();for(const list of [state.paymentAppointments,state.appointments,state.previewAppointments]){const a=list?.find(x=>x.id===id);if(a)Object.assign(a,updated)}drawDirectory()}catch(error){alert(error.message)}finally{button.disabled=false}
}
drawDirectory=function(){if(!state.auth)return previousDirectoryDraw();if(state.view==='clients')return drawClientsDirectory();if(state.view==='specialists')return drawSpecialistsDirectory();if(state.view==='services')return drawServicesDirectory();if(state.view==='payments')return drawPaymentsDirectory();return previousDirectoryDraw()}
function syncRoomLabel(){}function changeRoom(direction){const ids=['all',...state.rooms.map(x=>x.id)],current=ids.indexOf($('roomFilter').value);$('roomFilter').value=ids[(current+direction+ids.length)%ids.length];state.view='calendar';render()}
async function login(e){e.preventDefault();$('loginError').textContent='';state.auth=btoa(`${$('username').value}:${$('password').value}`);try{await load();sessionStorage.setItem('ft.auth',state.auth);sessionStorage.setItem('ft.username',$('username').value);$('loginDialog').close();$('accountName').textContent=$('username').value}catch(err){state.auth=null;sessionStorage.removeItem('ft.auth');$('loginError').textContent=err.message}}
const drawDirectoryWithRooms=drawDirectory;drawDirectory=function(){drawDirectoryWithRooms()}
function refreshRoomAvailabilityOptions(){const select=$('roomId'),start=new Date($('startsAt').value),end=new Date($('endsAt').value);if(!select||Number.isNaN(start)||Number.isNaN(end))return;if(state.editingId){for(const option of select.options){option.style.color='';option.dataset.busy='false';option.title=''}select.style.color='';return}for(const option of select.options){const busy=roomIsBusy(option.value,start,end);option.style.color=busy?'#9aa5a8':'';option.dataset.busy=busy?'true':'false';option.title=busy?'Gabinet zajęty w wybranym terminie':'Dostępny gabinet'}const selected=select.options[select.selectedIndex];select.style.color=selected?.dataset.busy==='true'?'#9aa5a8':''}
function newVisit(autoFind=true){cancelFirstSlotSearch();if(!state.auth){$('loginDialog').showModal();return}if(!state.clients.length||!state.specialists.length||!state.rooms.length){alert('Najpierw dodaj klienta, specjalistę i gabinet.');return}state.dateAnchor=null;state.editingId=null;$('deleteAppointment').hidden=true;$('deleteAppointment').disabled=false;$('appointmentEyebrow').textContent='NOWA REZERWACJA';$('appointmentTitle').textContent='Umów wizytę';$('appointmentSubmit').textContent='Zapisz wizytę';$('appointmentError').textContent='';fillServiceOptions();$('serviceId').value='';$('price').value='0';$('paid').checked=false;$('confirmed').checked=true;$('confirmed').disabled=false;$('note').value='';const filteredSpecialist=$('specialistFilter').value,filteredRoom=$('roomFilter').value;$('specialistId').value=filteredSpecialist==='all'?'':filteredSpecialist;$('roomId').value=filteredRoom==='all'?'':filteredRoom;const date=new Date();date.setSeconds(0,0);const specialistId=$('specialistId').value;const firstSchedule=state.schedules.filter(s=>s.specialistId===specialistId&&scheduleOccursOn(s,date)).sort((a,b)=>a.startTime.localeCompare(b.startTime))[0];const [hours,minutes]=(firstSchedule?.startTime||'09:00').slice(0,5).split(':').map(Number);date.setHours(hours,minutes,0,0);const end=new Date(date);end.setMinutes(end.getMinutes()+55);$('startsAt').value=inputDate(date);$('endsAt').value=inputDate(end);syncTimeInputsFromHidden();if(filteredSpecialist!=='all'&&filteredRoom==='all')suggestRoomIfNeeded(true);else refreshRoomAvailabilityOptions();$('appointmentDialog').showModal();refreshAppointmentDayPreview();if(autoFind!==false&&specialistId)setFirstAvailableSpecialistSlot()}
function newVisitAt(day,offset){const selected=$('specialistFilter').value;if(selected==='all'){alert('Aby umówić wizytę z kalendarza, wybierz jednego specjalistę w filtrze.');return}newVisit(false);$('specialistId').value=selected;let minute=Math.round(offset/5)*5;const date=new Date(`${day}T00:00:00`);date.setMinutes((calendarOpening()*60)+minute);const previous=state.appointments.filter(a=>a.specialistId===selected&&a.startsAt.startsWith(day)&&new Date(a.endsAt)<=date).sort((a,b)=>new Date(b.endsAt)-new Date(a.endsAt))[0];if(previous){const candidate=new Date(new Date(previous.endsAt).getTime()+5*60000);if(Math.abs(candidate-date)<=15*60000)date.setTime(candidate.getTime())}const end=new Date(date);end.setMinutes(end.getMinutes()+55);$('startsAt').value=inputDate(date);$('endsAt').value=inputDate(end);if($('roomFilter').value==='all'){const free=firstFreeRoom(date,end,selected);if(free)$('roomId').value=free.id}syncTimeInputsFromHidden();refreshRoomAvailabilityOptions();refreshAppointmentDayPreview()}
function edit(id){const a=state.appointments.find(x=>x.id===id);if(!a)return;cancelFirstSlotSearch();$('appointmentError').textContent='';$('deleteAppointment').hidden=false;$('deleteAppointment').disabled=false;state.dateAnchor=null;state.editingId=id;$('appointmentEyebrow').textContent='EDYCJA REZERWACJI';$('appointmentTitle').textContent=client(a.clientId);$('appointmentSubmit').textContent='Zapisz zmiany';$('clientId').value=a.clientId;$('specialistId').value=a.specialistId;$('roomId').value=a.roomId;fillServiceOptions(a.serviceId);$('serviceId').value=a.serviceId||'';$('startsAt').value=a.startsAt.slice(0,16);$('endsAt').value=a.endsAt.slice(0,16);$('price').value=a.price;$('paid').checked=a.paid;$('confirmed').checked=a.status!=='SCHEDULED';$('confirmed').disabled=!['SCHEDULED','CONFIRMED'].includes(a.status);$('note').value=a.note||'';$('recurrence').value=a.recurrenceType||'NONE';toggleRecurrence();refreshRoomAvailabilityOptions();$('appointmentDialog').showModal()}
async function save(e){e.preventDefault();const recurrence=$('recurrence').value,body={clientId:$('clientId').value,specialistId:$('specialistId').value,roomId:$('roomId').value,serviceId:$('serviceId').value||null,startsAt:$('startsAt').value,endsAt:$('endsAt').value,price:Number($('price').value),paid:$('paid').checked,confirmed:$('confirmed').disabled?null:$('confirmed').checked,note:$('note').value,recurrence,recurrenceEndDate:recurrence==='NONE'?null:$('recurrenceEndDate').value||null,recurrenceInterval:recurrence==='CUSTOM'?Number($('recurrenceInterval').value||1):null,recurrenceUnit:recurrence==='CUSTOM'?$('recurrenceUnit').value:null,recurrenceDays:recurrence==='CUSTOM'?[...document.querySelectorAll('#recurrenceDays input:checked')].map(x=>x.value):null,updateSeries:false};const original=state.appointments.find(x=>x.id===state.editingId);if(original?.recurrenceGroupId&&(original.startsAt!==body.startsAt||original.endsAt!==body.endsAt))body.updateSeries=confirm('To jest wizyta cykliczna. Czy wprowadzić zmianę daty lub godziny do tej oraz wszystkich kolejnych wizyt tej serii?');try{const r=await api(state.editingId?`/api/appointments/${state.editingId}`:'/api/appointments',{method:state.editingId?'PATCH':'POST',body:JSON.stringify(body)});if(!r.ok){const d=await r.json();throw Error(typeof d.message==='string'?d.message:'Nie można zapisać wizyty.')}state.calendarDate=body.startsAt.slice(0,10);state.weekStart=startOfWeek(new Date(body.startsAt));state.miniMonth=new Date(state.weekStart);$('appointmentDialog').close();await load()}catch(err){$('appointmentError').textContent=body.updateSeries?`${err.message} Nie można zmienić całej serii; możesz zapisać zmianę tylko tej jednej wizyty.`:err.message}}
function relatedAppointments(){const specialistId=$('specialistId').value,roomId=$('roomId').value;return state.appointments.filter(a=>a.id!==state.editingId&&(a.specialistId===specialistId||a.roomId===roomId))}
function formatLocal(d){return inputDate(d)}function syncDate(changed,other,side){const startEl=$('startsAt'),endEl=$('endsAt'),oldStart=state.formStart?new Date(state.formStart):null,oldEnd=state.formEnd?new Date(state.formEnd):null;let start=new Date(startEl.value),end=new Date(endEl.value);if(Number.isNaN(start)||Number.isNaN(end))return;$('appointmentError').textContent='';if(side==='start'&&oldStart&&oldEnd){end=new Date(oldEnd.getTime()+(start-oldStart));endEl.value=formatLocal(end)}if(side==='end'&&end<=start){const duration=oldStart&&oldEnd?Math.max(5*60000,oldEnd-oldStart):55*60000;start=new Date(end-duration);startEl.value=formatLocal(start)}start=new Date(startEl.value);end=new Date(endEl.value);if(side==='start'){const before=relatedAppointments().filter(a=>new Date(a.startsAt)<start&&new Date(a.endsAt)>start).sort((a,b)=>new Date(b.endsAt)-new Date(a.endsAt))[0];if(before){const duration=end-start;start=new Date(new Date(before.endsAt).getTime()+5*60000);end=new Date(start.getTime()+duration);startEl.value=formatLocal(start);endEl.value=formatLocal(end)}const next=relatedAppointments().filter(a=>new Date(a.startsAt)>start&&new Date(a.startsAt)<end).sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt))[0];if(next){end=new Date(new Date(next.startsAt).getTime()-5*60000);endEl.value=formatLocal(end);if(end<=start)$('appointmentError').textContent='Brak miejsca na tę wizytę między sąsiednimi rezerwacjami.'}}state.formStart=startEl.value;state.formEnd=endEl.value;state.dateAnchor=side}
function scheduleLabel(s){const days={MONDAY:'pon.',TUESDAY:'wt.',WEDNESDAY:'śr.',THURSDAY:'czw.',FRIDAY:'pt.',SATURDAY:'sob.',SUNDAY:'nd.'};const repeat={WEEKLY:'co tydzień',BIWEEKLY:'co drugi tydzień',MONTHLY:'co miesiąc',ONCE:'jednorazowo'};return `${s.startTime}–${s.endTime} · ${repeat[s.recurrence]}${s.recurrence==='ONCE'?'':` · ${s.daysOfWeek.map(x=>days[x]).join(', ')}`}`}
function renderSchedules(){const items=state.schedules.filter(x=>x.specialistId===state.editingSpecialistId);$('scheduleList').innerHTML=items.length?items.map(x=>`<div class="schedule-item"><button class="edit-specialist" data-delete-schedule="${x.id}" type="button">Usuń</button><button class="edit-specialist" data-edit-schedule="${x.id}" type="button">Edytuj</button><strong>${esc(scheduleLabel(x))}</strong><span>od ${x.startDate}${x.endDate?` do ${x.endDate}`:' · bez daty końcowej'}</span></div>`).join(''):'<p class="dialog-intro">Brak godzin pracy — nie można umawiać pacjentów.</p>'}
