function renderAlternativeRoomList(){const primary=$('editSpecialistPrimaryRoom').value,list=$('alternativeRoomList'),choice=$('alternativeRoomChoice');state.specialistAlternativeRooms=state.specialistAlternativeRooms.filter(id=>id!==primary&&state.rooms.some(r=>r.id===id));list.innerHTML=state.specialistAlternativeRooms.map((id,index)=>{const r=state.rooms.find(x=>x.id===id);return r?`<div class="alternative-room-item" draggable="true" data-alternative-room-id="${r.id}"><span class="drag-handle">⠿</span><span>${index+1}. ${esc(r.name)} (${esc(r.shortName||r.name)})</span><button type="button" aria-label="Usuń ${esc(r.name)}" data-remove-alternative-room="${r.id}">×</button></div>`:''}).join('')||'<small>Brak gabinetów alternatywnych.</small>';const available=state.rooms.filter(r=>r.id!==primary&&!state.specialistAlternativeRooms.includes(r.id));choice.innerHTML=available.length?available.map(r=>`<option value="${r.id}">${esc(r.name)} (${esc(r.shortName||r.name)})</option>`).join(''):'<option value="">Brak pozostałych gabinetów</option>';$('addAlternativeRoom').disabled=!available.length}
function fillSpecialistRoomPreferences(s){const primary=$('editSpecialistPrimaryRoom');primary.innerHTML='<option value="">Brak preferencji</option>'+state.rooms.map(r=>`<option value="${r.id}">${esc(r.name)} (${esc(r.shortName||r.name)})</option>`).join('');primary.value=s?.primaryRoomId||state.rooms[0]?.id||'';state.specialistAlternativeRooms=[...(s?.alternativeRoomIds||[])].filter(id=>id!==primary.value);renderAlternativeRoomList()}
function editSpecialist(id){const s=state.specialists.find(x=>x.id===id);if(!s)return;state.editingSpecialistId=id;$('specialistEyebrow').textContent='EDYCJA SPECJALISTY';$('specialistTitle').textContent=`${s.firstName} ${s.lastName}`;$('editSpecialistFirstName').value=s.firstName;$('editSpecialistLastName').value=s.lastName;$('editSpecialistSpecialization').value=s.specialization;$('editSpecialistColor').value=s.color;syncSpecialistColorPreview();fillSpecialistRoomPreferences(s);$('specialistError').textContent='';$('deleteSpecialist').hidden=false;$('scheduleEditor').hidden=false;$('scheduleForm').hidden=true;renderSchedules();$('specialistDialog').showModal()}
function newSpecialist(){const palette=['#2563eb','#db2777','#7c3aed','#0891b2','#65a30d','#d97706','#dc2626','#4f46e5'];state.editingSpecialistId=null;$('specialistEyebrow').textContent='NOWY SPECJALISTA';$('specialistTitle').textContent='Dodaj specjalistę';$('editSpecialistFirstName').value='';$('editSpecialistLastName').value='';$('editSpecialistSpecialization').value='';$('editSpecialistColor').value=palette.find(x=>!state.specialists.some(s=>s.color.toLowerCase()===x))||'#2563eb';syncSpecialistColorPreview();fillSpecialistRoomPreferences();$('specialistError').textContent='';$('deleteSpecialist').hidden=true;$('scheduleEditor').hidden=true;$('specialistDialog').showModal()}
async function saveSpecialist(e){e.preventDefault();const primaryRoomId=$('editSpecialistPrimaryRoom').value||null,body={firstName:$('editSpecialistFirstName').value,lastName:$('editSpecialistLastName').value,specialization:$('editSpecialistSpecialization').value,color:$('editSpecialistColor').value,primaryRoomId,alternativeRoomIds:state.specialistAlternativeRooms.filter(id=>id!==primaryRoomId)};try{const r=await api(state.editingSpecialistId?`/api/specialists/${state.editingSpecialistId}`:'/api/specialists',{method:state.editingSpecialistId?'PATCH':'POST',body:JSON.stringify(body)});if(!r.ok){const d=await r.json();throw Error(typeof d.message==='string'?d.message:'Nie można zapisać specjalisty.')}const saved=await r.json();await load();if(!state.editingSpecialistId){state.editingSpecialistId=saved.id;editSpecialist(saved.id)}else $('specialistDialog').close()}catch(err){$('specialistError').textContent=err.message}}
