    const result=['defaultPrice','suggestedDurationMinutes'].includes(key)?Number(a[key]??(key==='suggestedDurationMinutes'?55:0))-Number(b[key]??(key==='suggestedDurationMinutes'?55:0)):String(a[key]||'').localeCompare(String(b[key]||''),'pl',{numeric:true});
