  $('editServiceName').value=service?.name||'';
  $('editServiceDescription').value=service?.description||'';
  $('editServicePrice').value=service?.defaultPrice??0;
  $('editServiceDuration').value=service?.suggestedDurationMinutes??55;
  $('editServiceEquipment').value=service?.requiredEquipment||'';
