function cancelFirstSlotSearch(){state.firstSlotRequest=(state.firstSlotRequest||0)+1;$('appointmentSubmit').disabled=false}
function firstSpecialistSlot(specialistId,duration,now,lastDay,appointments){
  const schedules=state.schedules.filter(s=>s.specialistId===specialistId);
  const active=appointments.filter(a=>!['CANCELLED_BY_CLIENT','CANCELLED_BY_CLINIC','NO_SHOW'].includes(a.status));
  const preferred=$('roomId').value,rooms=[...state.rooms].sort((a,b)=>Number(b.id===preferred)-Number(a.id===preferred));
  for(const day=new Date(now.getFullYear(),now.getMonth(),now.getDate());day<=lastDay;day.setDate(day.getDate()+1)){
    const ranges=schedules.filter(s=>scheduleOccursOn(s,day)).map(s=>({start:new Date(`${iso(day)}T${s.startTime}`),end:new Date(`${iso(day)}T${s.endTime}`)})).sort((a,b)=>a.start-b.start);
    // Merge adjacent work periods so an appointment can span their boundary.
    const merged=[];for(const range of ranges){const previous=merged.at(-1);if(previous&&range.start<=previous.end){if(range.end>previous.end)previous.end=range.end}else merged.push(range)}
    for(const range of merged){
      let candidate=new Date(Math.ceil(Math.max(+range.start,+now)/60000)*60000);
      while(+candidate+duration*60000<=+range.end){
        const end=new Date(+candidate+duration*60000),overlaps=active.filter(a=>new Date(a.startsAt)<end&&new Date(a.endsAt)>candidate);
        const specialistConflicts=overlaps.filter(a=>a.specialistId===specialistId);
        const available=rooms.find(room=>!overlaps.some(a=>a.roomId===room.id));
        if(!specialistConflicts.length&&available)return {start:candidate,end,roomId:available.id};
        const conflicts=specialistConflicts.length?specialistConflicts:overlaps.filter(a=>rooms.some(room=>room.id===a.roomId));
        if(!conflicts.length)break;
        candidate=new Date(Math.ceil(Math.min(...conflicts.map(a=>+new Date(a.endsAt)))/60000)*60000);
      }
    }
  }
  return null;
}
async function setFirstAvailableSpecialistSlot(){
  if(state.editingId||!$('appointmentDialog').open||!$('specialistId').value)return;
  cancelFirstSlotSearch();const request=state.firstSlotRequest,specialistId=$('specialistId').value,duration=currentVisitDuration();
  const valid=()=>request===state.firstSlotRequest&&!state.editingId&&$('appointmentDialog').open&&$('specialistId').value===specialistId;
  $('appointmentSubmit').disabled=true;$('appointmentError').textContent='Szukam pierwszego wolnego terminu…';
  try{
    if(!state.schedules.some(s=>s.specialistId===specialistId))throw Error('Ten specjalista nie ma ustawionych godzin pracy.');
    const now=new Date(),lastDay=new Date(now);lastDay.setFullYear(lastDay.getFullYear()+1);
    const response=await api(`/api/appointments?from=${iso(now)}&to=${iso(lastDay)}`);
    if(!response.ok)throw Error('Nie udało się sprawdzić wolnych terminów. Spróbuj ponownie.');
    const appointments=await response.json();if(!valid())return;
    const slot=firstSpecialistSlot(specialistId,duration,new Date(),lastDay,appointments);
    if(!slot)throw Error('Brak wolnego terminu o tej długości w godzinach pracy specjalisty w ciągu najbliższych 12 miesięcy.');
    $('startsAt').value=inputDate(slot.start);$('endsAt').value=inputDate(slot.end);$('roomId').value=slot.roomId;
    state.formStart=$('startsAt').value;state.formEnd=$('endsAt').value;state.previewAppointments=appointments.filter(a=>a.startsAt.startsWith(iso(slot.start)));
    $('appointmentError').textContent='';syncTimeInputsFromHidden();refreshRoomAvailabilityOptions();refreshAppointmentDayPreview();
  }catch(error){if(valid()){$('startsAt').value='';$('endsAt').value='';$('appointmentDate').value='';$('startTime').value='';$('endTime').value='';$('appointmentError').textContent=error.message;renderAppointmentDayPreview()}}
  finally{if(valid())$('appointmentSubmit').disabled=false}
}

$('specialistId').addEventListener('change',()=>{cancelFirstSlotSearch();$('appointmentError').textContent='';const person=state.specialists.find(s=>s.id===$('specialistId').value);$('roomId').value=person?.primaryRoomId||'';if(!state.editingId&&person)setFirstAvailableSpecialistSlot();refreshAppointmentDayPreview()});
$('appointmentDialog').addEventListener('close',cancelFirstSlotSearch);
['appointmentDate','startTime','endTime','roomId','serviceId'].forEach(id=>$(id).addEventListener('change',()=>{cancelFirstSlotSearch();if($('appointmentError').textContent==='Szukam pierwszego wolnego terminu…')$('appointmentError').textContent=''},true));

function syncPendingHighlight(){const count=state.auth?Number(state.pendingCount)||0:0;if(!count)state.pendingHighlight=false;$('pendingFilter').hidden=count===0;$('pendingCount').textContent=count;$('pendingFilter').setAttribute('aria-pressed',String(!!state.pendingHighlight));calendar.classList.toggle('highlight-pending',!!state.pendingHighlight)}
$('pendingFilter').addEventListener('click',()=>{state.pendingHighlight=!state.pendingHighlight;syncPendingHighlight()});
function appointmentDeletionMessage(a){
  const start=new Date(a.startsAt),end=new Date(a.endsAt),time={hour:'2-digit',minute:'2-digit'};
  return `Czy na pewno chcesz usunąć tę wizytę?\n\nKlient: ${client(a.clientId)}\nData: ${start.toLocaleDateString('pl-PL',{day:'2-digit',month:'2-digit',year:'numeric'})}\nGodziny: ${start.toLocaleTimeString('pl-PL',time)}–${end.toLocaleTimeString('pl-PL',time)}\nSpecjalista: ${specialist(a.specialistId)}\nGabinet: ${room(a.roomId)}`;
}
async function deleteEditedAppointment(){
  const a=state.appointments.find(item=>item.id===state.editingId);
  if(!a||$('deleteAppointment').disabled)return;
  const scope=a.recurrenceGroupId?await chooseDeletionScope(a):(confirm(appointmentDeletionMessage(a))?'one':'cancel');
  if(!['one','series'].includes(scope))return;
  $('appointmentError').textContent='';$('deleteAppointment').disabled=true;$('appointmentSubmit').disabled=true;
  try{
    const response=await api(`/api/appointments/${a.id}${scope==='series'?'?deleteSeries=true':''}`,{method:'DELETE'});
    if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.message||'Nie udało się usunąć wizyty.')}
    const keep=item=>item.id!==a.id&&!(scope==='series'&&item.recurrenceGroupId===a.recurrenceGroupId&&item.startsAt>=a.startsAt);
    state.appointments=state.appointments.filter(keep);
    state.previewAppointments=state.previewAppointments.filter(keep);state.paymentAppointments=null;
    if(a.status==='SCHEDULED')state.pendingCount=Math.max(0,(state.pendingCount||0)-1);
    $('appointmentDialog').close();state.editingId=null;render();
    try{await load()}catch(_){alert('Wizyta została usunięta, ale nie udało się odświeżyć danych. Odśwież kalendarz.')}
  }catch(error){if(state.editingId===a.id)$('appointmentError').textContent=error.message}
  finally{$('deleteAppointment').disabled=false;$('appointmentSubmit').disabled=false}
}

$('deleteAppointment').addEventListener('click',deleteEditedAppointment);
async function shiftCalendar(direction){
 const date=calendarNavigationDate(direction);state.calendarDate=iso(date);state.weekStart=startOfWeek(date);state.miniMonth=new Date(date);state.pickerMonth=new Date(date);
 if(state.auth)await load();else render();
}
async function changeCalendarMode(){state.calendarMode=$('calendarMode').value;if(state.calendarMode==='week')state.showWeekends=true;else if(state.calendarMode==='workweek')state.showWeekends=false;$('showWeekends').checked=state.showWeekends;state.weekStart=startOfWeek(new Date(state.calendarDate+'T00:00:00'));if(state.auth)await load();else render()}
$('calendarMode').addEventListener('change',changeCalendarMode);
$('showWeekends').addEventListener('change',async()=>{state.showWeekends=$('showWeekends').checked;if(!shortCalendarView()){state.calendarMode=state.showWeekends?'week':'workweek';$('calendarMode').value=state.calendarMode}if(state.auth)await load();else render()});

