 if(startup){state.calendarMode=p.calendarMode;state.showWeekends=p.calendarMode==='week'?true:p.calendarMode==='workweek'?false:p.showWeekends;$('calendarMode').value=state.calendarMode;$('showWeekends').checked=state.showWeekends;}
 $('sidebarSummary').hidden=!p.showSummary;
 $('calendarSpecialistLegend').hidden=!p.showLegend;
 document.documentElement.style.setProperty('--primary',p.accentColor);
 document.documentElement.style.setProperty('--green',p.accentColor);document.documentElement.style.setProperty('--teal',p.accentColor);
 document.querySelector('.brand-logo').src=p.logo||'/logo-fabryka-terapii.png';
 document.querySelector('.brand-logo').alt=p.clinicName;document.querySelector('.mobile-brand').textContent=p.clinicName;
