 const company=`<div class="settings-card"><h4>Identyfikacja placówki</h4><div class="settings-grid">${settingInput('clinicName','Nazwa placówki','text','required maxlength="150"')}${settingInput('nip','NIP','text','pattern="[0-9]{10}|" maxlength="10"')}${settingInput('address','Adres','text','maxlength="500"')}${settingInput('phone','Telefon kontaktowy','tel','maxlength="40"')}${settingInput('email','E-mail placówki','email','maxlength="150"')}<label>Logo · PNG, JPEG, WebP (do 200 KB)<input id="settingsLogoFile" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="settings-logo-row"><img id="settingsLogoPreview" alt="Podgląd logo"><button type="button" class="today-button" id="resetSettingsLogo">Przywróć domyślne logo</button></div><p class="settings-help">Dane kontaktowe są zapisywane. Użycie ich w potwierdzeniach wymaga uruchomienia modułu powiadomień.</p></div><div class="settings-card"><h4>Godziny otwarcia</h4><div class="settings-grid">${settingInput('openingHour','Od godziny (0–22)','number','min="0" max="22" required')}${settingInput('closingHour','Do godziny (1–23)','number','min="1" max="23" required')}</div><p class="settings-help">Wspólny zakres widoczny w kalendarzu, niezależny od grafików specjalistów. Wizyty poza tym zakresem rozszerzają kalendarz.</p></div><div class="settings-card"><h4>Region</h4>${plannedFields([['Strefa czasowa','Europe/Warsaw'],['Waluta','PLN · zł']])}<p class="settings-help">Zmiana strefy i waluty wymaga obsługi przeliczeń oraz dat w całym systemie.</p></div>`;
 const appearance=`<div class="settings-card"><h4>Kolory systemu</h4>${settingInput('accentColor','Kolor akcentu','color')}<p class="settings-help">Kolor głównych przycisków i aktywnych elementów.</p></div><div class="settings-card"><h4>Kolory specjalistów</h4><p>Każdy specjalista ma własny, unikalny kolor. Zmienisz go w jego profilu.</p><div class="settings-specialists">${state.specialists.map(s=>`<button type="button" class="today-button" data-settings-specialist="${esc(s.id)}"><i style="background:${/^#[\da-f]{6}$/i.test(s.color)?s.color:'#0b786f'}"></i>${esc(s.firstName+' '+s.lastName)}</button>`).join('')||'<p>Nie dodano jeszcze specjalistów.</p>'}</div></div><div class="settings-card"><h4>Format i tydzień</h4>${plannedFields([['Format daty i czasu','DD.MM.RRRR · 24 godziny'],['Pierwszy dzień tygodnia','Poniedziałek'],['Nadawanie kolorów','Ręczna edycja w profilu specjalisty']])}<p class="settings-help">Dodatkowe formaty i automatyczne nadawanie kolorów są planowane.</p></div>`;
