 const templates=settingsPlanned('Szablony zostaną połączone z wysyłką powiadomień.')+`<div class="settings-card"><h4>Potwierdzenie wizyty</h4><textarea disabled rows="5">Dzień dobry {imie_klienta}, potwierdzamy wizytę: {data} o {godzina}. Specjalista: {specjalista}. Miejsce: {nazwa_placowki}, {adres}. Kontakt: {telefon}.</textarea><p class="settings-help">Zmienne: {imie_klienta}, {data}, {godzina}, {specjalista}, {usluga}, {nazwa_placowki}, {adres}, {telefon}, {link_odwolania}.</p></div>`;
 const online=settingsPlanned('Publiczny formularz i widget rezerwacji nie są jeszcze uruchomione.')+plannedFields([['Rezerwacje online','Wyłączone'],['Dostępne usługi','Wybór usług z katalogu'],['Horyzont rezerwacji','60 dni'],['Minimalny odstęp przed wizytą','24 godziny'],['Odwołanie online','Do 24 godzin przed wizytą'],['Ochrona formularza','CAPTCHA i wymagana zgoda'],['Link i kod osadzenia widgetu','Dostępne po uruchomieniu modułu']]);
