function calendarOpening(){return state.calendarOpening??7;}
function calendarClosing(){return state.calendarClosing??20;}
function calendarMinutes(){return (calendarClosing()-calendarOpening())*60;}

$("settingsForm").addEventListener("invalid",e=>{const section=e.target.closest("[data-settings-section]");if(section)openSettingsSection(section.dataset.settingsSection);},true);

function chooseDeletionScope(a){return new Promise(resolve=>{const dialog=$('deleteSeriesDialog');$('deleteSeriesDetails').textContent=appointmentDeletionMessage(a);dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue),{once:true});dialog.showModal()})}
function steppedPrice(value,direction){const amount=Number(value)||0;return Math.max(0,(direction>0?Math.floor(amount/10)+1:Math.ceil(amount/10)-1)*10)}
function adjustPrice(direction){$('price').value=steppedPrice($('price').value,direction).toFixed(2)}
$('priceUp').addEventListener('click',()=>adjustPrice(1));$('priceDown').addEventListener('click',()=>adjustPrice(-1));
$('price').addEventListener('keydown',event=>{if(['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();adjustPrice(event.key==='ArrowUp'?1:-1)}});

function visitNoun(count){return count===1?'wizyta':count%10>=2&&count%10<=4&&(count%100<12||count%100>14)?'wizyty':'wizyt'}
async function refreshSidebarSummary(direction='current'){
 if(!state.auth)return;if(direction!=='current')state.summaryBrowsing=true;const request=state.summaryRequest=(state.summaryRequest||0)+1;
 try{const query=new URLSearchParams({direction});if(state.summaryBrowsing&&state.summaryCursor)query.set('cursor',state.summaryCursor);const response=await api('/api/appointments/summary?'+query);if(!response.ok)throw Error('Nie udało się odświeżyć podsumowania.');const data=await response.json();if(request!==state.summaryRequest||!state.auth)return;
 state.summaryCursor=data.cursor;if(!data.hasPrevious)state.summaryBrowsing=false;$('todayCount').textContent=data.todayCount;$('todayCountLabel').textContent=visitNoun(data.todayCount)+' w grafiku';$('weekCount').textContent=data.weekCount;$('weekCountLabel').textContent=visitNoun(data.weekCount);
 $('nextAppointment').innerHTML=data.visits.map(a=>'<article class="upcoming-visit"><small>'+esc(new Date(a.startsAt).toLocaleString('pl-PL',{weekday:'long',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))+'</small><strong>'+esc(a.client)+'</strong><span>'+esc(a.specialist)+'</span></article>').join('')||'<span>Brak nadchodzących wizyt</span>';
 $('previousUpcoming').disabled=!data.hasPrevious;$('nextUpcoming').disabled=!data.hasNext;$('summaryError').textContent='';
 }catch(error){if(state.auth&&request===state.summaryRequest)$('summaryError').textContent=error.message}
}
$('previousUpcoming').addEventListener('click',()=>refreshSidebarSummary('previous'));$('nextUpcoming').addEventListener('click',()=>refreshSidebarSummary('next'));
setInterval(()=>{if(state.auth)refreshSidebarSummary()},60000);
$('logoutButton').addEventListener('click',logout);
function logout(){state.auth=null;state.summaryRequest=(state.summaryRequest||0)+1;cancelFirstSlotSearch();sessionStorage.removeItem('ft.auth');sessionStorage.removeItem('ft.username');for(const key of Object.keys(state)){if(Array.isArray(state[key]))state[key]=[]}state.paymentAppointments=null;clinicPreferences=null;document.body.replaceChildren();window.location.replace('/');}
document.addEventListener('click',event=>{if(!event.target.closest('.account-menu-wrap')){$('accountMenu').hidden=true;$('accountButton').setAttribute('aria-expanded','false')}});
